return Command.provideEffect(
  begun,
  CommandRegistration,
  Effect.gen(function* () {
    const identity = childIdentity(yield* CommandRegistration, command);
    const invocation = yield* CommandInvocation;
    yield* invocation.enter(identity);
    return identity;
  })
) as unknown as Registered<C>;

const openApi3Definition = {
  openapi: '3.1.0',
  components: {
    schemas: {
      [name]: {
        type: 'object',
        properties: processedProperties,
      },
    },
  },
} as unknown as OpenAPI3;

const { cause, code, stack, statusCode, meta, possibleFixes } = this as unknown as {
  cause: unknown;
  code: string | undefined;
  stack: string | undefined;
  statusCode: number | undefined;
  meta: Record<string, unknown> | undefined;
  possibleFixes: string[] | undefined;
};

payload.issues.push({
  input: payload.value,
  continue: true,
  ...issue,
} as unknown as z.core.$ZodRawIssue)

const defineTool = sdkTool as unknown as (
  name: string,
  description: string,
  inputSchema: ZodType,
  handler: (
    args: Record<string, unknown>
  ) => Promise<{ content: Array<{ type: 'text'; text: string }> }>
) => ClaudeAgentTool;

parameters: inputParameters as unknown as {
  type: 'object';
  properties: {
    [key: string]: {
      type: string;
      description?: string;
    };
  };
  required: string[];
},

parameters: {
  type: 'object',
  description: tool.description || '',
  properties: inputParameters?.properties || {},
  required: inputParameters?.required || [],
} as unknown as Schema,

return new FunctionTool(
  execute,
  {
    name: tool.slug,
    description: tool.description ?? tool.name ?? '',
    parameters: parameters as LlamaindexToolParameters,
  },
  jsonSchemaToZodSchema(parameters)
) as unknown as LlamaindexTool;

